import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/ON.DXVlsWbj.js";import{_ as s}from"./chunks/EN.P9aPnFBv.js";import{_ as o}from"./chunks/OFF.BrU7kQE-.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as r,a as l}from"./chunks/M-S-N2.DstR7-iA.js";import{_ as p,o as c,c as d,a3 as u}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"Chargement vers Cloud","description":"","frontmatter":{"source_hash":"5577d64214","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/cloud.md","filePath":"fr/use/cloud.md"}'),m={name:"fr/use/cloud.md"};function v(h,i,g,b,f,x){return c(),d("div",null,[...i[0]||(i[0]=[u('<div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Chargement vers Cloud</p></div><p>Le chargement vers le cloud vous permet d&#39;envoyer vos glycémies vers divers services cloud ou bases de données.<br> Cela permet de partager les données avec des appareils autres que xDrip et de produire des rapports.</p><h3 id="nightscout-sync-rest-api" tabindex="-1">Synchronisation Nightscout (REST-API) <a class="header-anchor" href="#nightscout-sync-rest-api" aria-label="Permalink to &quot;Synchronisation Nightscout (REST-API) {#nightscout-sync-rest-api}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Synchronisation Nightscout (REST-API)</p><p> L&#39;API REST est le moyen standard de se connecter à Nightscout</p></div><p><a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> est la méthode universelle pour partager vos valeurs de glycémie, créer des rapports et bien plus encore...</p><p>Une fois votre site Nightscout créé, activez la synchronisation pour envoyer les données depuis xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Activée<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> L&#39;API REST est le moyen standard de se connecter à Nightscout</p></div><p>Si vous voulez utiliser Nightscout pour partager vos glycémies, vérifiez que cette option est activée si vous utilisez un téléphone mobile avec une carte SIM et un forfait de données. Sinon, l&#39;envoi n&#39;aura lieu que lorsque vous êtes connecté à un réseau Wi-Fi, ce qui convient si vous utilisez Nightscout pour collecter des données pour vos rapports.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les données mobiles<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Charger même en utilisant les données mobiles</p></div><p>Si vous utilisez des filtres ou des plugins de calibration, vous pouvez sélectionner cette option pour envoyer à Nightscout les données telles qu&#39;affichées par xDrip, au lieu des données non calibrées/non filtrées.</p><div class="admonition xdripitem"><p class="admonition-title">Envoyer la glycémie affichée<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Utiliser le lissage du bruit et les plugins (si activés) pour les valeurs diffusées</p></div><p>L&#39;URL de base est composée de votre API_SECRET (ou d&#39;un jeton) et de l&#39;URL de votre site.<br> L&#39;exemple fourni dans la boîte de dialogue concernait un Nightscout hébergé sur Azure.</p><div class="admonition xdripitem"><p class="admonition-title">URL de base</p><p> Format: <a href="https://password@hostname/api/v1/" target="_blank" rel="noreferrer">https://password@hostname/api/v1/</a></p></div><p>Le format de l&#39;URL doit être le suivant :</p><p><strong><code>https://your-API_SECRET@your-site.domain.fqd/api/v1/</code></strong></p><p>Vous trouverez l&#39;API_SECRET dans les <a href="https://nightscout.github.io/nightscout/setup_variables/#nightscout-configuration" target="_blank" rel="noreferrer">variables</a> de votre Nightscout.</p><p>Vous pouvez aussi utiliser un <a href="https://nightscout.github.io/nightscout/security/#create-authentication-tokens-for-users" target="_blank" rel="noreferrer">jeton</a> admin pour vous authentifier ; l&#39;URL ressemblerait alors à ceci :</p><p><strong><code>https://xdrip-12ab34cd5678ef90@your-site.domain.fqd/api/v1/</code></strong></p><p>Contactez le fournisseur si vous utilisez un service hébergé.</p><div class="info custom-block"><p class="custom-block-title">Plusieurs sites</p><p>Si vous avez plusieurs sites Nightscout, xDrip peut envoyer vers plusieurs URL Nightscout <strong>séparées par des espaces</strong>.<br><em><strong>Seules les valeurs de glycémie sont envoyées vers la ou les URL secondaires, pas les traitements</strong></em></p></div><p>Si plusieurs appareils envoient vers Nightscout (ce qui n&#39;est pas recommandé), vous voudrez peut-être aussi télécharger les traitements depuis Nightscout pour voir les informations envoyées par les autres.</p><div class="admonition xdripitem"><p class="admonition-title">Télécharger les données<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Essayer également de télécharger des données depuis Nightscout</p></div><div class="warning custom-block"><p class="custom-block-title">Calibration automatique</p><p>Il s&#39;agit du même réglage <a href="./../calibrate/advancedcal.html#use-treatment-bg-values">Calibration automatique</a> que dans les calibrations. À utiliser avec précaution.</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration automatique<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Calibrer en utilisant les nouvelles valeurs de glycémies si les conditions semblent pouvoir le faire, sans demander confirmation (expérimental)</p></div><br><div class="admonition xdripitem"><p class="admonition-title">Options supplémentaires</p></div><p>Si votre Nightscout n&#39;est disponible que sur un serveur local (sur une IP privée), n&#39;essayez pas d&#39;envoyer de données vers Nightscout lorsque vous n&#39;êtes pas chez vous. Ignorez ceci pour un Nightscout dans le cloud.</p><div class="admonition xdripitem"><p class="admonition-title">Ne pas effectuer les chargements par LAN<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Pour les serveurs locaux avec des adresses 192.168.x.x, ne pas essayer de charger quand il n’y a aucune connectivité réseau local.</p></div><p>Vous pouvez envoyer le niveau de batterie de votre transmetteur ou de votre capteur (si pris en charge).</p><div class="admonition xdripitem"><p class="admonition-title">Charger la batterie du transmetteur<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Envoyer votre niveau de batterie du transmetteur à Nightscout. Décocher si votre capteur de batterie ne marche pas.</p></div><div class="admonition xdripitem"><p class="admonition-title">Envoyer le niveau de batterie de l&#39;émetteur Dexcom<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Envoyer les statistiques de la batterie du Dexcom à Nightscout. Inclut toutes les données affichées sur l&#39;écran Statut du Collecteur.</p></div><p>Vous pouvez envoyer les <a href="./mainUI.html#treatments">traitements</a> saisis localement vers le <a href="https://nightscout.github.io/nightscout/setup_variables/#careportal-careportal" target="_blank" rel="noreferrer">Care Portal</a> de Nightscout.</p><div class="admonition xdripitem"><p class="admonition-title">Charger les traitements<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Envoyer des données de traitement à Nightscout. Décochez si votre portail ne marche pas.</p></div><p>Vous pouvez configurer une alerte en cas d&#39;échec de l&#39;envoi, et ajouter des informations aux données de glycémie envoyées.</p><div class="admonition xdripitem"><p class="admonition-title">Alerter en cas d&#39;échecs<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Afficher et émettre une notification si le chargement vers Nightscout échoue.</p></div><div class="admonition xdripitem"><p class="admonition-title">Ajouter les informations sources au nom du périphérique<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Pour Dex, envoie le type de collecteur (par exemple OB1) et le statut de remplissage des valeurs (natives) vers Nightscout.</p></div><h5 id="backfill-data-to-nightscout" tabindex="-1">Envoyer l&#39;historique vers Nightscout <a class="header-anchor" href="#backfill-data-to-nightscout" aria-label="Permalink to &quot;Envoyer l&#39;historique vers Nightscout {#backfill-data-to-nightscout}&quot;">​</a></h5><p>Si vous avez créé récemment un site Nightscout et voulez y envoyer vos données historiques depuis la base de données de xDrip, vous pouvez utiliser la récupération d&#39;historique (back-fill).</p><div class="admonition xdripitem"><p class="admonition-title">Réécrire les données</p><p> Envoyer les valeurs BG vers l&#39;historique de récupération</p></div><p>Sélectionnez le premier jour de la période à envoyer (jusqu&#39;à aujourd&#39;hui) et appuyez sur <strong>DO IT!</strong><br> Selon la quantité de données et la vitesse du réseau, l&#39;envoi peut prendre très longtemps (des heures).</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Nightscout Backfill</p><p>Choose the date for the oldest record to send to Nightscout. Use with care!</p><div style="background-color:gray;color:white;text-align:center;">  FEBRUARY 12, 2022 11:29PM </div><p><span style="background-color:gray;color:white;text-align:center;">  DO IT! </span> ANNULER</p></div><h3 id="mongodb" tabindex="-1">MongoDB <a class="header-anchor" href="#mongodb" aria-label="Permalink to &quot;MongoDB {#mongodb}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Cette méthode est obsolète pour Nightscout.</p></div><p>Vous pouvez envoyer directement les glycémies et l&#39;état de l&#39;appareil vers une base de données Mongo.</p><div class="admonition xdripitem"><p class="admonition-title">MongoDB</p><p> Téléchargement direct de la base de données, non recommandé pour Nightscout</p></div><p>L&#39;envoi vers MongoDB est obsolète depuis le rachat de mLab par MongoDB et la migration de beaucoup d&#39;utilisateurs vers Atlas : <strong>vous ne pouvez pas utiliser d&#39;URI de type DNS seed <code>mongodb+srv</code></strong>.<br> N&#39;utilisez cette fonction que si vous gérez votre propre base de données <a href="https://github.com/mongodb/mongo" target="_blank" rel="noreferrer">Mongo</a> ; le port par défaut est 27017.</p><p>La structure de l&#39;<a href="https://www.mongodb.com/docs/manual/reference/connection-string/#connection-string-uri-format" target="_blank" rel="noreferrer">URI de chaîne de connexion</a> est :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongodb://databaseusername:databasepassword@your.mongo.url/databasename</span></span></code></pre></div><p>Pour que la base de données reste compatible avec Nightscout, ne modifiez pas Nom de la Collection ni Nom de la Collection d&#39;état du périphérique par rapport aux valeurs par défaut (si vous les modifiez, vous devrez aussi modifier les variables correspondantes dans Nightscout, <code>MONGODB_COLLECTION</code> et <code>MONGO_DEVICESTATUS_COLLECTION</code>).</p><div class="info custom-block"><p class="custom-block-title">Info</p><p>Les données envoyées peuvent ne pas s&#39;afficher dans la page web de Nightscout, mais seulement dans les rapports Nightscout.</p></div><h3 id="influxdb" tabindex="-1">InfluxDB <a class="header-anchor" href="#influxdb" aria-label="Permalink to &quot;InfluxDB {#influxdb}&quot;">​</a></h3><p>Vous pouvez aussi envoyer les données vers une base <a href="https://www.influxdata.com/products/influxdb-overview/" target="_blank" rel="noreferrer">InfluxDB</a> et utiliser Grafana pour les présenter.</p><div class="admonition xdripitem"><p class="admonition-title">InfluxDB</p><p> Si vous utilisez une base de données privée InfluxDB, ceci doit être activé</p></div><p>Notez que votre URI InfluxDB s&#39;exprime ainsi :</p><p><code>https://host_address:port</code>, par exemple pour un serveur local : <code>https://192.168.0.56:8086</code></p><h3 id="dex-share" tabindex="-1">Dex Share <a class="header-anchor" href="#dex-share" aria-label="Permalink to &quot;Dex Share {#dex-share}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Votre nom d&#39;utilisateur ne peut pas être un numéro de téléphone</p><p>Créez un <a href="https://www.dexcom.com/faqs/how-do-i-create-a-dependent-account" target="_blank" rel="noreferrer">compte dépendant</a> pour avoir un nom d&#39;utilisateur composé uniquement de texte.<br> Une fois le nouveau compte dépendant créé, vérifiez que vous êtes connecté avec ce compte dans vos applications Dexcom et recréez tous les abonnés.</p></div><p>Une fois que vous avez un abonné actif, créé par les applications Dexcom, vous pouvez utiliser xDrip pour envoyer les données vers Dexcom Share.</p><div class="admonition xdripitem"><p class="admonition-title">Chargement Dexcom Share</p><p> Chargement des données vers les serveurs Dexcom afin que vous puissiez utiliser vos données avec des applications Dexcom</p></div><div class="info custom-block"><p class="custom-block-title">Info</p><p>Vous pouvez envoyer vos glycémies vers Dexcom Share, <strong>pas vers Dexcom Clarity</strong>.</p></div><div class="admonition xdripitem"><p class="admonition-title">Charger les valeurs BG vers Dexcom Share<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Activer ceci pour charger vers les serveurs Dexcom Share</p></div><p>Si vous utilisez un compte américain, activez cette option ; <strong>pour tout autre pays, laissez-la désactivée</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Compte Dex basé aux USA<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Activé = votre compte et les applications abonnés sont aux USA</p></div><p>Saisissez les identifiants que vous utilisez pour vous connecter à Clarity.</p><div class="admonition xdripitem"><p class="admonition-title">Utilisateur du compte Dexcom Share</p><p> Votre login pour le site Dexcom Share</p></div><div class="admonition xdripitem"><p class="admonition-title">Mot de passe de compte Dexcom Share</p><p> Votre mot de passe pour le compte Dexcom Share</p></div><h3 id="tidepool" tabindex="-1">Tidepool <a class="header-anchor" href="#tidepool" aria-label="Permalink to &quot;Tidepool {#tidepool}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Tidepool</p><p> Envoyer les données au service Tidepool</p></div><p>Si vous avez un compte <a href="https://www.tidepool.org/" target="_blank" rel="noreferrer">Tidepool</a>, vous pouvez y envoyer automatiquement vos données et les partager avec votre endocrinologue.<br> Si xDrip peut afficher les <a href="./display.html#basal-information">informations de basale provenant d&#39;un état externe</a>, elles seront aussi envoyées vers Tidepool.</p><div class="admonition xdripitem"><p class="admonition-title">Synchroniser vers Tidepool<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><p>Saisissez votre adresse e-mail et votre mot de passe (ceux utilisés lors de votre <a href="https://app.tidepool.org/signup/personal" target="_blank" rel="noreferrer">inscription</a>).</p><div class="admonition xdripitem"><p class="admonition-title">Nom d&#39;utilisateur</p><p>Votre nom d&#39;utilisateur Tidepool, normalement votre adresse e-mail</p></div><div class="admonition xdripitem"><p class="admonition-title">Mot de passe de connexion</p><p>Mot de passe de connexion Tidepool</p></div><p>Une fois cela fait, testez la connexion.</p><div class="admonition xdripitem"><p class="admonition-title">Test de la connexion Tidepool</p></div><p>Tidepool n&#39;a pas besoin de données en temps réel : sélectionnez avec le curseur la période d&#39;envoi des données. La valeur par défaut est de 15 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Age des données (15)</p></div><p>N&#39;utilisez <strong>PAS</strong> les serveurs de test (laissez l&#39;option désélectionnée).</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les serveurs d&#39;Intégration (test)<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>Vous pouvez choisir de n&#39;envoyer les données que dans certaines conditions, pour économiser la batterie et les frais de données.</p><div class="admonition xdripitem"><p class="admonition-title">Uniquement lors de la charge<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Télécharger des données uniquement pendant la charge</p></div><div class="admonition xdripitem"><p class="admonition-title">Seulement en Wi-Fi<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Télécharger des données uniquement lorsque vous êtes connecté à un réseau illimité comme le Wifi</p></div><p>Si vous envoyez aussi manuellement les données de votre pompe, vous voudrez peut-être désactiver l&#39;envoi des traitements par xDrip pour éviter les doublons.</p><div class="admonition xdripitem"><p class="admonition-title">Ne pas télécharger les traitements<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Télécharger uniquement les données MGC pour éviter les doublons avec l&#39;envoi manuel de la pompe</p></div><h5 id="web-deposit" tabindex="-1">Web Deposit <a class="header-anchor" href="#web-deposit" aria-label="Permalink to &quot;Web Deposit {#web-deposit}&quot;">​</a></h5><p>Web Deposit est une API simple d&#39;envoi par lots, utilisée actuellement pour le diagnostic. Elle est cachée derrière le Mode développeur et n&#39;est pas destinée à un usage courant.</p><h3 id="nightlite" tabindex="-1">NightLite <a class="header-anchor" href="#nightlite" aria-label="Permalink to &quot;NightLite {#nightlite}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">NightLite</p><p> Lightweight Nightscout compatible service intended for followers</p></div><p>NightLite est un service d&#39;abonné léger et compatible Nightscout, une alternative plus simple à l&#39;hébergement de votre propre site Nightscout si vous avez seulement besoin de partager votre glycémie avec des abonnés.</p><p>Consultez la <a href="./nightlite.html">configuration de l&#39;abonné NightLite</a> pour la procédure d&#39;installation complète.</p><div class="admonition xdripitem"><p class="admonition-title">Upload to NightLite<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Whether to upload to the remote service</p></div><div class="admonition xdripitem"><p class="admonition-title">NightLite URL</p><p> Typically entered by scanning QR code from dashboard<br>  This contains your security key - do not disclose it</p></div><p>Une fois l&#39;option activée, vous pouvez afficher un QR code contenant vos informations de connexion NightLite, que vos abonnés pourront scanner.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher le code QR</p></div><h3 id="nocturne" tabindex="-1">Nocturne <a class="header-anchor" href="#nocturne" aria-label="Permalink to &quot;Nocturne {#nocturne}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Nocturne</p><p> Télécharger vers Nocturne API V4</p></div><p><a href="https://getnocturne.dev/" target="_blank" rel="noreferrer">Nocturne</a> est le successeur moderne de Nightscout proposé par la Nightscout Foundation. Si vous gérez votre propre instance Nocturne, xDrip peut y envoyer directement les données.</p><div class="admonition xdripitem"><p class="admonition-title">Activer l&#39;envoi vers Nocturne<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><p>Saisissez l&#39;adresse de votre instance Nocturne.</p><div class="admonition xdripitem"><p class="admonition-title">URL de l&#39;instance Nocturne</p><p> Entrez l&#39;URL de votre instance Nocturne (par exemple <a href="https://mynocturne.example.com" target="_blank" rel="noreferrer">https://mynocturne.example.com</a>)</p></div><p>Autorisez ensuite xDrip auprès de votre instance. Aucun mot de passe n&#39;est stocké dans xDrip : un code s&#39;affiche, que vous saisissez dans le navigateur sur la page d&#39;approbation de votre instance Nocturne pour finaliser la connexion.</p><div class="admonition xdripitem"><p class="admonition-title">Se connecter à Nocturne</p><p> Autorisez xDrip+ avec votre instance Nocturne</p></div><h4 id="quick-connect-from-nocturne" tabindex="-1">Connexion rapide depuis Nocturne <a class="header-anchor" href="#quick-connect-from-nocturne" aria-label="Permalink to &quot;Connexion rapide depuis Nocturne {#quick-connect-from-nocturne}&quot;">​</a></h4><p>Au lieu de saisir l&#39;URL de l&#39;instance, laissez Nocturne configurer xDrip pour vous. Dans votre instance Nocturne, ouvrez Connectors &amp; Apps, puis Set Up an Uploader, et sélectionnez xDrip+ dans la liste CGM Apps.</p><img src="'+r+'" style="zoom:75%;"><p>La page Set up xDrip+ affiche un QR code Quick Connect.</p><img src="'+l+'" style="zoom:60%;"><div class="warning custom-block"><p class="custom-block-title">Scannez ce QR code avec l&#39;application appareil photo de votre téléphone, pas avec xDrip</p><p>Le QR code Quick Connect est un lien qui ouvre xDrip sur votre téléphone directement dans la configuration du connecteur Nocturne. Le scanner avec l&#39;importateur de paramètres <a href="./copysettings.html#auto-configure">Configuration automatique</a> de xDrip ne fonctionnera pas.</p></div><p>xDrip affiche alors un code d&#39;autorisation. Saisissez-le dans le champ Enter Authorization Code de cette même page Nocturne et appuyez sur Continue pour finaliser la connexion.</p><h4 id="alternate-method-settings-qr-code" tabindex="-1">Autre méthode : QR code de paramètres <a class="header-anchor" href="#alternate-method-settings-qr-code" aria-label="Permalink to &quot;Autre méthode : QR code de paramètres {#alternate-method-settings-qr-code}&quot;">​</a></h4><p>Si vous préférez préparer vous-même les paramètres Nocturne, utilisez le configurateur ci-dessous. Saisissez l&#39;URL de votre instance, choisissez ce qu&#39;il faut envoyer, puis scannez le QR code généré depuis xDrip avec <a href="./copysettings.html#auto-configure">Configuration automatique</a> (Caméra, ou QR code depuis un fichier avec le PNG téléchargé). xDrip liste les paramètres et demande confirmation avant de les appliquer.</p><div class="info custom-block"><p class="custom-block-title">Contrairement au QR code Quick Connect ci-dessus, celui-ci doit être scanné avec xDrip, pas avec l&#39;application appareil photo.</p></div><p>Une fois les paramètres importés, ouvrez Paramètres, Chargement vers Cloud, Nocturne, appuyez sur Se connecter à Nocturne et saisissez sur votre instance Nocturne le code d&#39;autorisation affiché par xDrip. Les jetons d&#39;autorisation ne font jamais partie du QR code.</p><iframe src="../../use/nocturne-qr.html" title="xDrip+ Nocturne QR configurator" style="width:100%;height:800px;border:1px solid #d9dee5;border-radius:8px;background:#f6f7f9;" loading="lazy"></iframe><p>Vous pouvez aussi <a href="../../use/nocturne-qr.html" target="_blank">ouvrir le configurateur dans une page séparée</a>.</p><p>Sélectionnez les données à envoyer. Les glycémies sont activées par défaut ; tout le reste est facultatif.</p><div class="admonition xdripitem"><p class="admonition-title">Upload SGV<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Télécharger les glycémies du capteur CGM</p></div><div class="admonition xdripitem"><p class="admonition-title">Charger les traitements<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger des bolus, des glucides, des notes et des événements de l&#39;appareil</p></div><div class="admonition xdripitem"><p class="admonition-title">Télécharger les calibrations<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les étalonnages du capteur</p></div><div class="admonition xdripitem"><p class="admonition-title">Télécharger les tests sanguins<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les résultats du lecteur de glycémie</p></div><div class="admonition xdripitem"><p class="admonition-title">Télécharger la fréquence cardiaque<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les données de fréquence cardiaque</p></div><div class="admonition xdripitem"><p class="admonition-title">Télécharger le nombre de pas<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les données du nombre de pas</p></div><div class="admonition xdripitem"><p class="admonition-title">Télécharger le statut de l&#39;appareil<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger le niveau de batterie du téléphone et le statut de charge</p></div><div class="admonition xdripitem"><p class="admonition-title">Télécharger le suivi des mouvements<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Télécharger les classifications d&#39;activité reconnues</p></div><div class="admonition xdripitem"><p class="admonition-title">Utiliser les données mobiles<span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Autoriser les téléversements via les données mobiles</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',127)])])}const T=p(m,[["render",v]]);export{C as __pageData,T as default};
